    private void ResultadoActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_ResultadoActionPerformed
        double CampoNumero1 = Double.parseDouble(this.CampoNumero1.getText());
        double CampoNumero2 = Double.parseDouble (this.CampoNumero2.getText());
        double resultado = CampoNumero1 + CampoNumero2;

        this.Resultado.setText (String.valueOf(resultado));
    }//GEN-LAST:event_ResultadoActionPerformed

    private void resultadoooActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_resultadoooActionPerformed
         double CampoNumero1 = Double.parseDouble(this.CampoNumero1.getText());
        double CampoNumero2 = Double.parseDouble (this.CampoNumero2.getText());
        double resultado = CampoNumero1 / CampoNumero2;

        this.Resultado.setText (String.valueOf(resultado));
    }//GEN-LAST:event_resultadoooActionPerformed

    private void calcularActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_calcularActionPerformed
       double CampoNumero1 = Double.parseDouble(this.CampoNumero1.getText());
        double CampoNumero2 = Double.parseDouble (this.CampoNumero2.getText());
        double resultado = CampoNumero1 - CampoNumero2;

        this.Resultado.setText (String.valueOf(resultado)); 
    }//GEN-LAST:event_calcularActionPerformed

    private void calculoActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_calculoActionPerformed
        double CampoNumero1 = Double.parseDouble(this.CampoNumero1.getText());
        double CampoNumero2 = Double.parseDouble (this.CampoNumero2.getText());
        double resultado = CampoNumero1 * CampoNumero2;

        this.Resultado.setText (String.valueOf(resultado));
    }//GEN-LAST:event_calculoActionPerformed

